import { and, eq } from "drizzle-orm";
import { getDb, notificationPreferences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, toPreference } from "./_mappers";
import { NOTIFICATION_KINDS } from "@/types/notification";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { OrgId, UserId } from "@/types/common";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export async function listPreferences(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly NotificationPreference[]> {
  const rows = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
      ),
    )
    .all();
  const stored = new Map(rows.map((row) => [row.kind, toPreference(row)]));
  return NOTIFICATION_KINDS.map(
    (kind) =>
      stored.get(kind) ?? {
        orgId,
        userId,
        kind,
        inApp: true,
        email: true,
        digestOnly: false,
      },
  );
}

/**
 * `null` means "no explicit row" — the fan-out then falls back to the default
 * channel set rather than treating the absence as "everything off".
 */
export async function getPreference(
  orgId: OrgId,
  userId: UserId,
  kind: NotificationKind,
): Promise<NotificationPreference | null> {
  const row = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
        eq(notificationPreferences.kind, kind),
      ),
    )
    .get();
  return row ? toPreference(row) : null;
}

export async function upsertPreference(
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  const row = getDb()
    .insert(notificationPreferences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      kind: input.kind,
      inApp: input.inApp,
      email: input.email,
      digestOnly: input.digestOnly,
    })
    .onConflictDoUpdate({

        await notifyUnblockedDependents(
          payload.orgId,
          [payload.issueId],
          payload.actorId,
        );
      }
    }),
    subscribe("issue.archived", async (payload) => {
      const blocker = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (blocker && blocker.status !== "done" && blocker.status !== "canceled") {
        await notifyUnblockedDependents(
          payload.orgId,
          [payload.issueId],
          payload.actorId,
        );
      }
    }),
    subscribe("project.archived", async (payload) => {
      if (payload.archivedIssueIds && payload.archivedIssueIds.length > 0) {
        await notifyUnblockedDependents(
          payload.orgId,
          payload.archivedIssueIds,
          payload.actorId,
        );
      }
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/** Dedupes dependents when one operation closes multiple blockers at once. */
async function notifyUnblockedDependents(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const dependentIds = new Set<IssueId>();
  for (const blockerId of blockerIds) {
    const dependents = await issueDependencyRepo.listDependents(orgId, blockerId);
    for (const dependent of dependents) dependentIds.add(dependent.id);
  }

  for (const issueId of dependentIds) {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    if (
      !issue ||
      issue.archivedAt !== null ||
      issue.status === "done" ||
      issue.status === "canceled" ||
      issue.assigneeId === null
    ) {
      continue;
    }

    const openBlockerIds = await issueDependencyRepo.listOpenBlockerIds(
      orgId,
      issue.id,
    );
    if (openBlockerIds.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "Issue unblocked",
      body: `Issue ${issue.id} has no open blockers remaining`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

