import {
  and,
  asc,
  eq,
  isNull,
  notInArray,
} from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, toIssue } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

function toIssueDependency(
  row: typeof issueDependencies.$inferSelect,
): IssueDependency {
  return {
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Follows existing blocked-by links from `blockerId` to detect a cycle. */
export async function wouldCreateCycle(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .select({
      issueId: issueDependencies.issueId,
      blockerId: issueDependencies.blockerId,
    })
    .from(issueDependencies)
    .where(orgPredicate(issueDependencies.orgId, orgId))
    .all();
  const blockersByIssue = new Map<IssueId, IssueId[]>();
  for (const row of rows) {
    const dependentId = brandId<IssueId>(row.issueId);
    const linkedBlockerId = brandId<IssueId>(row.blockerId);
    const linked = blockersByIssue.get(dependentId) ?? [];
    linked.push(linkedBlockerId);
    blockersByIssue.set(dependentId, linked);
  }

  const visited = new Set<IssueId>();
  const pending = [blockerId];
  while (pending.length > 0) {
    const current = pending.pop()!;
    if (current === issueId) return true;
    if (visited.has(current)) continue;
    visited.add(current);
    pending.push(...(blockersByIssue.get(current) ?? []));
  }
  return false;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toIssueDependency(row);
}

export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const deleted = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .get();
  return deleted !== undefined;
}

/** Includes closed blockers but excludes archived blockers, ordered by issue number. */
export async function listBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ blocker: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(asc(issues.number))
    .all();
  const labels = await listLabelsForIssues(
    orgId,
    rows.map(({ blocker }) => brandId<IssueId>(blocker.id)),
  );
  return rows.map(({ blocker }) =>
    toIssue(
      blocker,
      (labels[blocker.id] ?? []).map((label) => label.id),
    ),
  );
}

export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        isNull(issues.archivedAt),
        notInArray(issues.status, ["done", "canceled"]),
      ),
    )
    .all();
  return rows.map(({ blockerId }) => brandId<IssueId>(blockerId));
}

/** All issues linked to this blocker, including archived or closed dependents. */
export async function listDependents(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ dependent: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.issueId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map(({ dependent }) => toIssue(dependent));
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { IssueBlockedError } from "@/server/services/issue-dependency-service";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof IssueBlockedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

