/** Live issue ids about to be archived by a project cascade. */
export async function listLiveIssueIdsForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .all();
  return rows.map(({ id }) => id as IssueId);
}

